"use strict";(self.webpackChunkmy_site=self.webpackChunkmy_site||[]).push([["4404"],{7819(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/Differential Geometry and Fibre Bundle/1_1","metadata":{"permalink":"/zh/blog/Differential Geometry and Fibre Bundle/1_1","source":"@site/i18n/zh/docusaurus-plugin-content-blog/Differential Geometry and Fibre Bundle/1_1.mdx","title":"\u62D3\u6251\u57FA\u7840","description":"\u6211\u4EEC\u8FD9\u91CC\u9ED8\u8BA4\u5927\u5BB6\u719F\u6089\u96C6\u5408\u7684\u4E00\u4E9B\u57FA\u7840\u5B9A\u4E49\u548C\u6982\u5FF5\u3002\u5BF9\u4E8E\u7269\u7406\u7528\u5FAE\u5206\u51E0\u4F55\u800C\u8A00\uFF0C\u6211\u4EEC\u5E76\u4E0D\u9700\u8981\u592A\u591A\u62D3\u6251\u7684\u77E5\u8BC6\u3002\u5982\u679C\u5728\u9605\u8BFB\u7684\u65F6\u5019\u9047\u5230\u56F0\u96BE\u53EF\u4EE5\u5148\u8DF3\u8FC7\uFF0C\u5B83\u51E0\u4E4E\u4E0D\u4F1A\u5F71\u54CD\u540E\u9762\u7684\u7406\u89E3\u3002","date":"2026-05-15T00:00:00.000Z","tags":[{"inline":true,"label":"\u4E2D\u6587","permalink":"/zh/blog/tags/\u4E2D\u6587"}],"readingTime":4.84,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\u62D3\u6251\u57FA\u7840","date":"2026-05-15T00:00:00.000Z","tags":["\u4E2D\u6587"]},"unlisted":false},"content":"> \u6211\u4EEC\u8FD9\u91CC\u9ED8\u8BA4\u5927\u5BB6\u719F\u6089\u96C6\u5408\u7684\u4E00\u4E9B\u57FA\u7840\u5B9A\u4E49\u548C\u6982\u5FF5\u3002\u5BF9\u4E8E\u7269\u7406\u7528\u5FAE\u5206\u51E0\u4F55\u800C\u8A00\uFF0C\u6211\u4EEC\u5E76\u4E0D\u9700\u8981\u592A\u591A\u62D3\u6251\u7684\u77E5\u8BC6\u3002\u5982\u679C\u5728\u9605\u8BFB\u7684\u65F6\u5019\u9047\u5230\u56F0\u96BE\u53EF\u4EE5\u5148\u8DF3\u8FC7\uFF0C\u5B83\u51E0\u4E4E\u4E0D\u4F1A\u5F71\u54CD\u540E\u9762\u7684\u7406\u89E3\u3002\\n\\n# \u5B9A\u4E49\uFF1A\u62D3\u6251\\n\\n\u6570\u5B66\u5BB6\u63D0\u5230\u7684\u62D3\u6251\u548C\u7269\u7406\u5B66\u5BB6\u63D0\u5230\u7684\u6709\u4E00\u4E9B\u5FAE\u5999\u7684\u4E0D\u540C\u3002\u6211\u4EEC\u8FD9\u91CCfollow\u6570\u5B66\u5BB6\u4E25\u8C28\u7684\u5B9A\u4E49\uFF1A\\n\\n:::tip[\u62D3\u6251]\\n\\n\u7ED9\u5B9A\u4E00\u4E2A\u96C6\u5408 $X$\uFF0C\u6211\u4EEC\u6784\u5EFA\u53E6\u4E00\u4E2A\u96C6\u5408 $\\\\mathscr{T}$\uFF0C\u5176\u4E2D\u5305\u542B$X$\u7684\u6240\u6709\u201C\u5F00\u5B50\u96C6\u201D\uFF0C\u8FD9\u4E2A\u96C6\u5408 $\\\\mathscr{T}$ \u5C31\u88AB\u79F0\u4E3A$X$\u7684\u62D3\u6251\u3002 \\n\\n:::\\n\\n:::info[\u62D3\u6251\u9700\u8981\u6EE1\u8DB3\u7684\u6761\u4EF6]\\n\\n\u4E3A\u4E86\u4F7F\u5F97\u6211\u4EEC\u5BF9\u62D3\u6251\u548C\u5F00\u96C6\u7684\u5B9A\u4E49\u662F\u81EA\u6D3D\u7684\uFF0C$\\\\mathscr{T}$\u9700\u8981\u6EE1\u8DB3\u5982\u4E0B\u7684\u4E09\u4E2A\u6761\u4EF6\uFF1A\\n \\n1. $X, \\\\varnothing \\\\in \\\\mathscr{T}$;\\n2. \u82E5 $\\\\ O_i \\\\in \\\\mathscr{T},  i = 1,  2,  \\\\dots,  n$\uFF0C\u5219 $\\\\bigcap\\\\limits_{i=1}^n O_i \\\\in \\\\mathscr{T}$;\\n3. \u82E5 $\\\\ O_i \\\\in \\\\mathscr{T},  \\\\forall i$\uFF0C\u5219 $\\\\bigcup\\\\limits_{i} O_i \\\\in \\\\mathscr{T}$. \\n\\n:::\\n\\n:::note[\u5907\u6CE8]\\n\\n\u8FD9\u91CC\u8981\u6CE8\u610F\uFF1A\u7B2C\u4E8C\u6761\u8981\u6C42\u6709\u9650\u591A\u4E2A\u5F00\u96C6\u7684\u4EA4\u96C6\u624D\u80FD\u4FDD\u6301\u5F00\u96C6\uFF1B\u800C\u7B2C\u4E09\u6761\u5E76\u6CA1\u6709\u5BF9\u5E76\u96C6\u7684\u6570\u91CF\u63D0\u51FA\u8981\u6C42\uFF0C\u5373\u65E0\u9650\u591A\u4E2A\u5F00\u96C6\u7684\u5E76\u96C6\u4ECD\u7136\u4FDD\u6301\u5F00\u3002\u4E3E\u4E2A\u4F8B\u5B50, \u8003\u8651: $U_n = \\\\{x | \\\\left|x\\\\right| < 1+ \\\\frac{1}{n} \\\\}$, \u5219 $\\\\bigcap\\\\limits_{i=1}^\\\\infty U_n \\\\to [-1,  1]$\u3002\u8FD9\u4E0D\u662F $\\\\mathbb{R}$ \u7684\u4E00\u4E2A\u5F00\u5B50\u96C6!\\n\\n:::\\n\\n## \u4E3E\u4F8B\uFF1A\u4E0D\u540C\u79CD\u7C7B\u7684\u62D3\u6251\\n\\n\u8FD9\u91CC\u6211\u4EEC\u4E3E\u4E09\u4E2A\u7279\u6B8A\u7684\u4F8B\u5B50\u3002\u4E8B\u5B9E\u4E0A\u7ED9\u5B9A\u4E00\u4E2A\u96C6\u5408 $X$\uFF0C\u901A\u5E38\u6709\u65E0\u7A77\u591A\u79CD\u9009\u53D6\u62D3\u6251\u7684\u65B9\u6CD5\u3002\\n\\n:::info[\u901A\u5E38\u62D3\u6251]\\n\\n\u8BBE$X = \\\\mathbb{R}^n$, \u5219\u5176**\u901A\u5E38\u62D3\u6251\u4E3A** $\\\\mathscr{T}_u = \\\\{\\\\varnothing, \\\\bigcup_{x_0, r} B(x_0, r)\\\\}$\u3002\u8FD9\u91CC $B(x_0, r) = \\\\{x \\\\in \\\\mathbb{R}^n| \\\\left|x-x_0\\\\right| < r\\\\}$\uFF0C\u5176\u4E2D $x_0 \\\\in \\\\mathbb{R}^n, r>0 \\\\in \\\\mathbb{R}$ \u88AB\u79F0\u4F5C\u5F00\u7403\u3002 \\n\\n\u8FD9\u91CC $\\\\mathbb{R}^n$ \u4E2D\u7684\u8DDD\u79BB\u6309\u7167\u901A\u5E38\u7684\u65B9\u5F0F\u5B9A\u4E49: $\\\\left|x-x_0\\\\right| = \\\\sqrt{\\\\sum_{\\\\mu=1}^n(x^\\\\mu-x_0^\\\\mu)^2}$. \u6CE8\u610F\uFF1A\u8FD9\u91CC $x^\\\\mu$ \u4EE3\u8868 $x$ \u7684\u7B2C $\\\\mu$ \u5206\u91CF\uFF0C\u800C\u4E0D\u662F\u5E42\u6307\u6570\u3002\u8FD9\u662F\u5FAE\u5206\u51E0\u4F55\u7684\u60EF\u7528\u7EA6\u5B9A\u3002\\n\\n\u4E8B\u5B9E\u4E0A\uFF0C\u8FD9\u53EA\u662F $\\\\mathbb{R}$ \u4E0A\u5F00\u533A\u95F4\u7684\u76F4\u63A5\u63A8\u5E7F\u3002\\n:::\\n\\n:::info[\u79BB\u6563\u62D3\u6251]\\n\\n\u5BF9\u4E8E\u4EFB\u610F\u4E00\u4E2A\u96C6\u5408 $X$, \u6211\u4EEC\u5B9A\u4E49\u5176\u62D3\u6251 $\\\\mathscr{T}$ \u4E3A $X$ \u7684\u5168\u90E8\u5B50\u96C6\u3002\u8FD9\u662F\u4E00\u4E2A\u6709\u70B9\u65E0\u804A\u7684\u5B9A\u4E49\u3002\\n\\n:::\\n\\n:::info \u51DD\u805A\u62D3\u6251\\n\\n\u5BF9\u4E8E\u4EFB\u610F\u4E00\u4E2A\u96C6\u5408 $X$, \u5B9A\u4E49\uFF1A $\\\\mathscr{T} = \\\\{\\\\varnothing, X\\\\}$\u3002\u8FD9\u540C\u6837\u662F\u4E00\u4E2A\u65E0\u804A\u7684\u5B9A\u4E49\u3002\\n\\n:::\\n\\n# \u5B9A\u4E49\uFF1A\u8FDE\u7EED\u6027\\n\\n\u5BF9\u4E8E\u4E00\u4E2A\u901A\u5E38\u610F\u4E49\u4E0A\u7684\u4E00\u5143\u51FD\u6570 $f(x)$\uFF0C\u6211\u4EEC\u662F\u7528 $\\\\varepsilon-\\\\delta$ \u8BED\u8A00\u5B9A\u4E49\u5B83\u7684\u8FDE\u7EED\u6027\u7684\uFF1A\\n\\n:::note[\u8FDE\u7EED\u6027\uFF1A $\\\\varepsilon-\\\\delta$ \u8BED\u8A00]\\n\\n\u82E5 $\\\\forall \\\\varepsilon > 0$, $\\\\exists \\\\delta >0$, \u4F7F\u5F97\u5F53 $\\\\left|f(x) - f(x_0)\\\\right| < \\\\varepsilon $ \u65F6, \u6709 $\\\\left|x-x_0\\\\right| < \\\\delta$. \\n\\n:::\\n\\n\u4F46\u662F\u6211\u4EEC\u73B0\u5728\u53EA\u6709\u4E00\u4E2A\u62D3\u6251\u7A7A\u95F4, \u8FD9\u4E0A\u9762\u5927\u6982\u7387\u6CA1\u6709\u826F\u597D\u5B9A\u4E49\u7684\u52A0\u51CF\u6CD5, \u66F4\u6CA1\u6709\u529E\u6CD5\u5B9A\u4E49\u4E00\u4E2A\u201C\u987A\u5E8F\u201D, \u4E5F\u5C31\u6CA1\u6709\u529E\u6CD5\u6BD4\u8F83\u5927\u5C0F\u3002\u540C\u65F6\u6211\u4EEC\u4E5F\u6CA1\u6709\u4E00\u4E2A\u201C\u5EA6\u91CF\u201D\u6765\u8861\u91CF\u4E24\u4E2A\u5143\u7D20\u95F4\u7684\u201C\u8DDD\u79BB\u201D\u3002\u56E0\u6B64\u6211\u4EEC\u8F6C\u800C\u5BFB\u627E\u529E\u6CD5\u62D3\u5C55\u8FDE\u7EED\u6027\u7684\u5B9A\u4E49\u3002\u5BF9\u4E8E\u62D3\u6251\u7A7A\u95F4\uFF0C\u6211\u4EEC\u53EA\u6709\u529E\u6CD5\u8861\u91CF\u5F00\u96C6\uFF0C\u56E0\u6B64\u6211\u4EEC\u9700\u8981\u7528\u96C6\u5408\u7684\u8BED\u8A00\u6765\u91CD\u65B0\u8868\u8FF0$\\\\varepsilon-\\\\delta$\u8BED\u8A00\uFF1A\\n\\n:::hint[\u8FDE\u7EED\u6027\uFF1A\u96C6\u5408\u8BED\u8A00]\\n\\n\u82E5\u6620\u5C04 $f$ \u7684\u50CF $f[X]$ \u7684\u4EFB\u610F\u5F00\u5B50\u96C6 $U$, \u5176\u539F\u50CF $f^{-1}[U]$ \u90FD\u662F\u5F00\u5B50\u96C6, \u5219 $f$ \u8FDE\u7EED. \\n\\n:::\\n\\n\u4E4D\u4E00\u770B\u8FD9\u4E2A\u5B9A\u4E49\u597D\u50CF\u6CA1\u6709\u4EFB\u4F55\u9053\u7406, \u4F46\u662F\u6211\u4EEC\u7684\u786E\u53EF\u4EE5\u8BC1\u660E\u5B83\u662F\u4E0E $\\\\varepsilon-\\\\delta$ \u8BED\u8A00\u5728 $\\\\mathbb{R}$ \u4E0A\u662F\u7B49\u4EF7\u7684\uFF08\u4E8B\u5B9E\u4E0A, \u5BF9\u4E8E\u4EFB\u4F55\u4E00\u4E2A\u914D\u5907\u4E86\u5EA6\u91CF\u7684\u62D3\u6251\u7A7A\u95F4\u90FD\u662F\u6210\u7ACB\u7684\uFF09\u3002\u6211\u4EEC\u8FD9\u91CC\u7565\u53BB\u5BF9\u8FD9\u4E2A\u7B49\u4EF7\u6027\u7684\u8BC1\u660E\uFF0C\u56E0\u4E3A\u4F5C\u4E3A\u7269\u7406\u4EBA\uFF0C\u6211\u4EEC\u6CA1\u6709\u5FC5\u8981\u5173\u6CE8\u592A\u591A\u7684\u7EC6\u8282\u3002\u4E0D\u8FC7\u8FD9\u4E2A\u8BC1\u660E\u662F\u5F88\u7B80\u5355\u7684\uFF0C\u5C1D\u8BD5\u5229\u7528\u5F00\u7403\u7684\u5B9A\u4E49\u5373\u53EF\u3002\\n\\n\u5BF9\u4E8E\u4E00\u822C\u7684\u51FD\u6570, \u6211\u4EEC\u7528 $C^r$ \u6765\u6307\u4EE3\u5B83\u4E00\u76F4\u5230 $r$ \u9636\u5BFC\u51FD\u6570\u5B58\u5728\u4E14\u8FDE\u7EED, \u7279\u522B\u5730, $C^0$ \u6307\u8FDE\u7EED\u51FD\u6570\u3001$C^\\\\infty$ \u6307\u5149\u6ED1\u51FD\u6570. \u6211\u4EEC\u5C06\u5BF9\u4E8E\u66F4\u4E00\u822C\u5730\u6620\u5C04\u6CBF\u7528\u8FD9\u4E2A\u79F0\u547C\u3002\u6CE8\u610F\uFF1A\u5BF9\u4E8E\u53EA\u5305\u542B\u4E86\u62D3\u6251\u7ED3\u6784\u7684\u96C6\u5408\u800C\u8A00, \u5B9A\u4E49\u5728\u5176\u4E0A\u7684\u6620\u5C04\u7684\u6700\u9AD8\u8981\u6C42\u5C31\u662F $C^0$\u3002\\n\\n# \u5B9A\u4E49\uFF1A\u540C\u80DA\\n\\n\u540C\u80DA\u662F\u4E00\u4E2A\u7528\u6765\u8861\u91CF\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4\u201C\u6709\u591A\u76F8\u4F3C\u201D\u7684\u6620\u5C04\u3002\u5177\u4F53\u800C\u8A00\uFF0C\u6211\u4EEC\u5B9A\u4E49\uFF1A\\n\\n:::hint[\u540C\u80DA]\\n\\n\u5982\u679C\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4 $(X,  \\\\mathscr{T})$\uFF0C $(Y,  \\\\mathscr{S})$ \u4E4B\u95F4\u5B58\u5728\u4E00\u4E2A\u6620\u5C04$f$\uFF0C\u6EE1\u8DB3\u4EE5\u4E0B\u6761\u4EF6\uFF1A\\n\\n1. $f$ \u4E3A\u53CC\u5C04\uFF1B\\n2. $f,  f^{-1}$ \u7686\u4E3A\u8FDE\u7EED\u6620\u5C04\uFF0C\\n\\n\u5219\u79F0\u8FD9\u4E24\u4E2A\u62D3\u6251\u7A7A\u95F4\u4E92\u76F8**\u540C\u80DA**\uFF0C$f$\u662F\u4E00\u4E2A\u540C\u80DA\u6620\u5C04\u3002 \\n\\n:::\\n\\n:::note[\u5907\u6CE8]\\n\\n\u4E00\u822C\u800C\u8A00, \u5982\u679C $f$ \u4E3A\u8FDE\u7EED\u6620\u5C04, \u5176\u9006\u4E5F\u5B58\u5728, \u5219\u5176\u9006\u6620\u5C04\u4E5F\u8FDE\u7EED\u3002\u7136\u800C\uFF0C\u4F60\u53EF\u4EE5\u7528\u524D\u9762\u63D0\u5230\u7684\u79BB\u6563\u62D3\u6251\u548C\u51DD\u805A\u62D3\u6251\u5F3A\u884C\u5B9A\u4E49\u4E00\u4E2A\u53CD\u4F8B\u51FA\u6765\uFF1A\u4EE4$(X,  \\\\mathscr{T})$ \u7684\u62D3\u6251\u4E3A\u79BB\u6563\u62D3\u6251\uFF08\u6240\u6709\u7684\u5B50\u96C6\u90FD\u662F\u5F00\u5B50\u96C6\uFF09\uFF0C$(Y,  \\\\mathscr{S})$ \u7684\u62D3\u6251\u4E3A\u51DD\u805A\u62D3\u6251\uFF08\u53EA\u6709$Y$\u548C$\\\\varnothing$\u662F\u5F00\u5B50\u96C6\uFF09\uFF0C\u5219\u5BF9\u4E8E\u4EFB\u610F\u53CC\u5C04 $f$ \u90FD\u662F\u8FDE\u7EED\u7684\uFF1A\u53EA\u6709 $Y=f[X]$ \u4E3A\u5F00\u5B50\u96C6, \u800C\u5176\u539F\u50CF $f^{-1}[Y]=X$ \u4E5F\u662F\u5F00\u96C6\uFF1B\u4F46\u5BF9\u4E8E\u4EFB\u610F\u9006\u6620\u5C04 $f^{-1}$ \u90FD\u4E0D\u662F\u8FDE\u7EED\u7684\uFF1A\u4EFB\u610F\u5B50\u96C6 $U \\\\subseteq X$ \u90FD\u662F\u5F00\u5B50\u96C6\uFF0C\u7136\u800C\u5176\u539F\u50CF $f^{-1}[U]$ \u90FD\u4E0D\u662F\u5F00\u5B50\u96C6\uFF0C\u9664\u975E$U=X$\u3002\u8FD9\u662F\u79BB\u6563\u62D3\u6251\u548C\u51DD\u805A\u62D3\u6251\u51E0\u4E4E\u552F\u4E00\u7684\u5E94\u7528\uFF0C\u548C\u5B83\u4EEC\u7684\u5B9A\u4E49\u4E00\u6837\u65E0\u804A\u3002\\n\\n:::"}]}}')}}]);